      }],
      uiSlots: [{ id: "due-detail", slot: "task.detail", title: "截止与过期", fields: [{ key: "dueAt", label: "截止时间" }, { key: "expired", label: "已过期" }], actions: [{ commandId: "setDue", label: "设截止" }] }],
